import{_ as t,o,c as n,a2 as i}from"./chunks/framework.vLhlLNVn.js";const f=JSON.parse('{"title":"Why does my device not connect or keep dropping?","description":"","frontmatter":{"order":3,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/04.fehlerbehebung/03.verbindung.md"},"headers":[],"relativePath":"adapter/esphome/fehlerbehebung/verbindung.md","filePath":"adapter/esphome/fehlerbehebung/verbindung.md","lastUpdated":null}'),a={name:"adapter/esphome/fehlerbehebung/verbindung.md"};function d(r,e,s,c,h,l){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="why-does-my-device-not-connect-or-keep-dropping" tabindex="-1">Why does my device not connect or keep dropping? <a class="header-anchor" href="#why-does-my-device-not-connect-or-keep-dropping" aria-label="Permalink to &quot;Why does my device not connect or keep dropping?&quot;">​</a></h1><p><a id="devices-offline-reporting-incorrect-password"></a></p><h2 id="why-are-all-devices-offline-or-reporting-incorrect-password-after-a-restart-or-update" tabindex="-1">Why are all devices offline or reporting &quot;incorrect password&quot; after a restart or update? <a class="header-anchor" href="#why-are-all-devices-offline-or-reporting-incorrect-password-after-a-restart-or-update" aria-label="Permalink to &quot;Why are all devices offline or reporting &quot;incorrect password&quot; after a restart or update?&quot;">​</a></h2><p>At startup the adapter sets <code>info._online</code> of all devices to <code>false</code>. It then reads address and credentials from the device objects and reconnects to every device. It does not need discovery for this. Until every device has answered, some are still offline.</p><p>If a device stays offline, check the tab &quot;Devices&quot; or <code>info._connectionStatus</code>:</p><table tabindex="0"><thead><tr><th>Status</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>API password incorrect</code></td><td>The device no longer accepts the password, e.g. since ESPHome 2026.1</td><td>&quot;Change connection settings&quot;, enter the key</td></tr><tr><td><code>Encryption Key Missing</code></td><td>The device now uses a key</td><td>same</td></tr><tr><td><code>unreachable</code></td><td>Device off or at another address</td><td>Check device and address</td></tr></tbody></table><p>If the address has changed, delete the device in the tab &quot;Devices&quot; and add it at the new address. A fixed address in the router prevents this.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erstes-geraet#api-password-still-work-esphome">API password and ESPHome 2026.1</a></p><p><a id="device-disconnect-every-few-seconds"></a></p><h2 id="why-does-my-device-disconnect-every-few-seconds" tabindex="-1">Why does my device disconnect every few seconds? <a class="header-anchor" href="#why-does-my-device-disconnect-every-few-seconds" aria-label="Permalink to &quot;Why does my device disconnect every few seconds?&quot;">​</a></h2><p>The adapter pings every connected device at the ping interval. If as many answers are missing as set in &quot;Ping attempts before offline&quot;, it drops the connection and re-establishes it. With the default of one attempt, a single lost ping is enough on weak Wi-Fi. The log then repeatedly shows <code>Connection to device &lt;IP&gt; lost …</code> and <code>ESPHome client … disconnected</code>.</p><ol><li>In the main settings under &quot;Connection behavior for known devices&quot;, set &quot;Ping attempts before offline&quot; to <code>3</code>.</li><li>Check the Wi-Fi signal of the device, e.g. with a <code>wifi_signal</code> sensor.</li><li>If that does not help, set <code>power_save_mode: none</code> under <code>wifi:</code> in the YAML and flash again.</li></ol><p><strong>See also:</strong> <a href="./../referenz/einstellungen#reconnect-settings-exist-happens-device">Connection settings</a></p><p><a id="device-initialisation-needed-object-tree"></a></p><h2 id="why-is-there-a-device-initialisation-needed-in-the-object-tree" tabindex="-1">Why is there a device &quot;Initialisation needed&quot; in the object tree? <a class="header-anchor" href="#why-is-there-a-device-initialisation-needed-in-the-object-tree" aria-label="Permalink to &quot;Why is there a device &quot;Initialisation needed&quot; in the object tree?&quot;">​</a></h2><p>&quot;Initialisation needed&quot; is the placeholder name of a device you added that never answered. The adapter only learns the real name on the first connection. Until then it writes the status of the attempt under <code>esphome.0.Initialisation needed.info</code>.</p><ol><li>Check address and key in the tab &quot;Devices&quot;. The device is listed there by its address.</li><li>Delete the entry and add the device again with the correct data.</li><li>If the folder &quot;Initialisation needed&quot; is still in the tab &quot;Objects&quot; afterwards, delete it there.</li></ol><p>After a restart of the instance the adapter no longer tries such a device, because it never saved it as a device.</p>',18)])])}const u=t(a,[["render",d]]);export{f as __pageData,u as default};
